import test from 'node:test';
import assert from 'node:assert/strict';
import {createRequire} from 'node:module';
import {expenseSqlite} from './helpers/expense-sqlite.mjs';
import {DailySheetBadge} from '../dist/sheets/daily-sheet-badge.js';
const require=createRequire(import.meta.url),auth=require('../dist/sheets/google-auth.js');
function setup(){
 const h=expenseSqlite();Object.assign(h.env,{RUNTIME_MODE:'production',DAILY_BADGE_WRITER_ENABLED:'true',DAILY_EDIT_COORDINATION_ENABLED:'true',EXPENSE_GENERATION_WORKER_ENABLED:'true',EXPENSE_STABLE_PROJECTION_ENABLED:'true',DAILY_LEGACY_WRITER_GATE_ENABLED:'true',GOOGLE_SPREADSHEET_ID:'workbook_private',SHEET_EXPENSE_DAILY:'daily'});
 h.sqlite.exec("INSERT INTO daily_legacy_writer_gates VALUES('workbook_private','daily','HOLD','fixture_1','now'); INSERT INTO expense_projection_cutovers VALUES('workbook_private','daily','fixture_1','ACTIVE',0,'now'); INSERT INTO daily_edit_coordination(spreadsheet_id,sheet_name,state,updated_at) VALUES('workbook_private','daily','AVAILABLE',strftime('%Y-%m-%dT%H:%M:%fZ','now'))");
 const ranges=[{namedRangeId:'id_state',name:'MLP_DAILY_STATUS',range:{sheetId:7,startRowIndex:0,endRowIndex:1,startColumnIndex:1,endColumnIndex:2}},{namedRangeId:'id_time',name:'MLP_DAILY_STATUS_TIME',range:{sheetId:7,startRowIndex:0,endRowIndex:1,startColumnIndex:2,endColumnIndex:3}}],cells=[{userEnteredFormat:{textFormat:{fontSize:11}}},{userEnteredFormat:{horizontalAlignment:'CENTER'}}],sheet={properties:{sheetId:7,title:'daily',gridProperties:{rowCount:100,columnCount:25,frozenRowCount:3}},merges:[],protectedRanges:[]};let posts=0,hook=null;
 const oldFetch=globalThis.fetch,oldToken=auth.getGoogleAccessToken;auth.getGoogleAccessToken=async()=> 'synthetic-token';
 globalThis.fetch=async(url,init={})=>{const u=new URL(String(url));if(init.method==='POST'){posts++;const body=JSON.parse(init.body);assert.equal(body.valueInputOption,'RAW');assert.deepEqual(body.data.map(x=>x.range),['MLP_DAILY_STATUS','MLP_DAILY_STATUS_TIME']);for(let i=0;i<2;i++){const v=body.data[i].values[0][0];if(v==='')delete cells[i].userEnteredValue;else cells[i].userEnteredValue={stringValue:v};}if(hook)await hook();return new Response(JSON.stringify({totalUpdatedCells:2,responses:[{},{}]}));}if(u.searchParams.has('ranges'))return new Response(JSON.stringify({spreadsheetId:'workbook_private',sheets:[{properties:{sheetId:7,title:'daily'},data:ranges.map((r,i)=>({startRow:r.range.startRowIndex,startColumn:r.range.startColumnIndex,rowData:[{values:[cells[i]]}]}))}]}));return new Response(JSON.stringify({spreadsheetId:'workbook_private',namedRanges:ranges,sheets:[sheet]}));};
 return {...h,badge:new DailySheetBadge(h.env),ranges,cells,sheet,posts:()=>posts,setHook:f=>hook=f,close(){globalThis.fetch=oldFetch;auth.getGoogleAccessToken=oldToken;h.close();}};
}
function state(h){return h.sqlite.prepare('SELECT state FROM daily_sheet_badge_journal').get()?.state;}
test('default-off blocks all Google operations',async()=>{const h=setup();try{h.env.DAILY_BADGE_WRITER_ENABLED='false';await assert.rejects(h.badge.register(),/DISABLED/);assert.equal(h.posts(),0);assert.equal(state(h),undefined);}finally{h.close();}});
test('register, resolve moved identities, publish and restore only the original blank values',async()=>{const h=setup();try{const originals=structuredClone(h.cells);assert.equal(await h.badge.register(),true);for(const r of h.ranges){r.range.startColumnIndex+=2;r.range.endColumnIndex+=2;}assert.equal(await h.badge.publish(),true);assert.equal(h.cells[0].userEnteredValue.stringValue,'ตรวจ');assert.match(h.cells[1].userEnteredValue.stringValue,/^\d\d\/\d\d\/\d\d\n\d\d:\d\d:\d\d$/);assert.equal(await h.badge.restore(),true);assert.deepEqual(h.cells,originals);assert.equal(state(h),'RESTORED');assert.equal(await h.badge.publish(),false);assert.equal(h.posts(),2);}finally{h.close();}});
test('rebinding, value, formatting, note, and merge changes require review without write',async()=>{for(const mode of ['id','value','format','note','merge']){const h=setup();try{assert.equal(await h.badge.register(),true);if(mode==='id')h.ranges[0].namedRangeId='changed';if(mode==='value')h.cells[0].userEnteredValue={stringValue:'human'};if(mode==='format')h.cells[0].userEnteredFormat={textFormat:{fontSize:20}};if(mode==='note')h.cells[0].note='human';if(mode==='merge')h.sheet.merges.push({startRowIndex:0,endRowIndex:1,startColumnIndex:1,endColumnIndex:3});await assert.rejects(h.badge.publish(),/REVIEW/);assert.equal(state(h),'REVIEW');assert.equal(h.posts(),0);}finally{h.close();}}});
test('unknown provider acknowledgement after write is held and never blindly replayed',async()=>{const h=setup();try{assert.equal(await h.badge.register(),true);h.setHook(()=>{throw Error('lost response');});await assert.rejects(h.badge.publish(),/REVIEW/);assert.equal(state(h),'REVIEW');assert.equal(await h.badge.publish(),false);assert.equal(h.posts(),1);}finally{h.close();}});
test('changed coordination during provider call holds even a successful response',async()=>{const h=setup();try{assert.equal(await h.badge.register(),true);h.setHook(()=>h.sqlite.exec("UPDATE daily_edit_coordination SET state='REVIEW'"));await assert.rejects(h.badge.publish(),/REVIEW/);assert.equal(state(h),'REVIEW');assert.equal(h.posts(),1);}finally{h.close();}});
test('two concurrent publishers dispatch at most once',async()=>{const h=setup();try{assert.equal(await h.badge.register(),true);const result=await Promise.allSettled([h.badge.publish(),h.badge.publish()]);assert.equal(result.filter(r=>r.status==='fulfilled'&&r.value).length,1);assert.equal(h.posts(),1);}finally{h.close();}});
test('duplicate identity, nonblank inputs, and protected cells cannot be registered',async()=>{for(const mode of ['duplicate','nonblank','protected']){const h=setup();try{if(mode==='duplicate')h.ranges.push({namedRangeId:'id_state',name:'unrelated',range:{sheetId:7,startRowIndex:4,endRowIndex:5,startColumnIndex:4,endColumnIndex:5}});if(mode==='nonblank')h.cells[0].userEnteredValue={formulaValue:'=1'};if(mode==='protected')h.sheet.protectedRanges.push({range:{sheetId:7,startRowIndex:0,endRowIndex:1,startColumnIndex:1,endColumnIndex:2}});if(mode==='nonblank')await assert.rejects(h.badge.register());else await assert.rejects(h.badge.register(),/STRUCTURE_INVALID/);assert.equal(state(h),undefined);assert.equal(h.posts(),0);}finally{h.close();}}});
async function noticeFixture(h,revise=false){
 const {ExpenseProjectionRuntimeJournal}=await import('../dist/sheets/expense-projection-runtime-journal.js');
 const {requestDailyEditNotice}=await import('../dist/sheets/daily-edit-coordination.js');
 Object.assign(h.env,{SHEET_EXPENSE_RAW:'raw',SHEET_PURCHASE_DETAILS:'detail'});
 h.sqlite.exec("INSERT INTO expense_events(expense_id,message_id,line_user_id,description,amount_satang,payment_key,source_wallet,category,transaction_date,status,created_at,version) VALUES('exp_fixture','msg','fixture','Synthetic',10000,'transfer','SHOP_BANK','general','2026-10-26','CONFIRMED','now',1); INSERT INTO sync_jobs(job_id,entity_type,entity_key,entity_version,trace_id,status,updated_at,lease_until,lease_token) VALUES('f','EXPENSE','exp_fixture',1,'fixture','PROCESSING','now','2099-01-01T00:00:00.000Z','owner'); INSERT INTO expense_projection_generation_jobs(spreadsheet_id,cutover_generation,expense_id,source_version,source_revision,state,lease_token,lease_until,created_at,updated_at) VALUES('workbook_private','fixture_1','exp_fixture',1,1,'IN_FLIGHT','generation_token','2099-01-01T00:00:00.000Z','now','now')");
 if(revise)h.sqlite.exec("UPDATE expense_events SET description=description WHERE expense_id='exp_fixture'; UPDATE expense_projection_generation_jobs SET source_revision=2");
 const job={kind:'SHEETS_SYNC',entityType:'EXPENSE',entityKey:'exp_fixture',entityVersion:1,traceId:'fixture'},generationLease={generation:'fixture_1',revision:revise?2:1,token:'generation_token'},syncLease='owner',outer=new ExpenseProjectionRuntimeJournal(h.env,job,syncLease,generationLease),context=await outer.context(),outerToken=await outer.begin('DAILY',context),windowToken='window_token_123456';assert.ok(outerToken);assert.equal(await requestDailyEditNotice(h.env,job,syncLease,generationLease,context,outerToken,windowToken,15),true);return{job,syncLease,generationLease,context,outerToken,windowToken,outer};
}
test('NOTICE receipt binds source and leases and starts wait after verified postimage',async()=>{const h=setup();try{assert.equal(await h.badge.register(),true);const b=await noticeFixture(h);assert.equal(await h.badge.publish(),false);assert.equal(await h.badge.publishNotice({...b,windowToken:'wrong_window_token'}),false);assert.equal(h.posts(),0);assert.equal(await h.badge.publishNotice(b),true);assert.equal(h.cells[0].userEnteredValue.stringValue,'พัก');assert.equal(h.posts(),1);const receipt=h.sqlite.prepare('SELECT * FROM daily_sheet_notice_receipts').get();assert.equal(receipt.window_token,b.windowToken);assert.equal(h.sqlite.prepare("SELECT round((julianday(ready_after)-julianday(observed_at))*86400) n FROM daily_sheet_notice_receipts").get().n,15);assert.equal(await h.badge.noticeEvidenceReady(b),false);assert.equal(await h.badge.publishNotice(b),false);assert.equal(h.posts(),1);advanceReceipt(h);assert.equal(await h.badge.noticeEvidenceReady(b),true);assert.equal(await b.outer.canDispatch('DAILY',b.outerToken,b.context),false);const original=structuredClone(h.cells[0].userEnteredFormat);h.cells[0].userEnteredFormat={textFormat:{fontSize:20}};assert.equal(await h.badge.noticeEvidenceReady(b),false);h.cells[0].userEnteredFormat=original;h.cells[0].userEnteredValue={stringValue:'human'};assert.equal(await h.badge.noticeEvidenceReady(b),false);}finally{h.close();}});
test('lost provider acknowledgement and changed generation lease cannot create usable receipt',async()=>{for(const mode of ['lost','lease']){const h=setup();try{assert.equal(await h.badge.register(),true);const b=await noticeFixture(h);h.setHook(()=>{if(mode==='lost')throw Error('lost acknowledgement');h.sqlite.exec("UPDATE expense_projection_generation_jobs SET lease_token='changed_token'");});await assert.rejects(h.badge.publishNotice(b),/REVIEW/);assert.equal(state(h),'REVIEW');assert.equal(h.sqlite.prepare('SELECT count(*) n FROM daily_sheet_notice_receipts').get().n,0);assert.equal(await h.badge.noticeEvidenceReady(b),false);assert.equal(h.posts(),1);}finally{h.close();}}});
test('lost D1 receipt or finalize acknowledgement holds and never grants notice evidence',async()=>{for(const phase of ['receipt','finalize']){const h=setup();try{assert.equal(await h.badge.register(),true);const b=await noticeFixture(h),prepare=h.DB.prepare;h.DB.prepare=function(sql){const s=prepare.call(this,sql);if(phase==='receipt'&&sql.includes('INSERT INTO daily_sheet_notice_receipts')||phase==='finalize'&&sql.includes('SET state=?,operation_token=NULL,verified_operation_token=')){const run=s.run.bind(s);s.run=async()=>{await run();throw Error('lost D1 acknowledgement');};}return s;};await assert.rejects(h.badge.publishNotice(b),/REVIEW/);h.DB.prepare=prepare;assert.equal(state(h),'REVIEW');assert.equal(await h.badge.noticeEvidenceReady(b),false);assert.equal(await h.badge.publishNotice(b),false);assert.equal(h.posts(),1);}finally{h.close();}}});
test('heartbeat refresh during NOTICE does not invalidate the bound window',async()=>{const h=setup();try{assert.equal(await h.badge.register(),true);const b=await noticeFixture(h);h.setHook(()=>h.sqlite.exec("UPDATE daily_edit_coordination SET updated_at=strftime('%Y-%m-%dT%H:%M:%fZ','now','+1 seconds')"));assert.equal(await h.badge.publishNotice(b),true);assert.equal(h.posts(),1);assert.equal(state(h),'READY');}finally{h.close();}});
// Test-only clock simulation; production retains immutable receipts.
function advanceReceipt(h){h.sqlite.exec("DROP TRIGGER daily_notice_receipt_no_update; UPDATE daily_sheet_notice_receipts SET observed_at=strftime('%Y-%m-%dT%H:%M:%fZ','now','-16 seconds'),ready_after=strftime('%Y-%m-%dT%H:%M:%fZ','now','-1 seconds'); CREATE TRIGGER daily_notice_receipt_no_update BEFORE UPDATE ON daily_sheet_notice_receipts BEGIN SELECT RAISE(ABORT,'daily receipt immutable'); END");}
async function readyNotice(h,revise=false){assert.equal(await h.badge.register(),true);const b=await noticeFixture(h,revise);assert.equal(await h.badge.publishNotice(b),true);advanceReceipt(h);return b;}
test('one receipt creates one durable intent under concurrency and exact source/lease fence',async()=>{const h=setup();try{const b=await readyNotice(h),results=await Promise.all([h.badge.consumeNotice(b),h.badge.consumeNotice(b)]),tokens=results.filter(Boolean);assert.equal(tokens.length,1);assert.equal(h.sqlite.prepare('SELECT count(*) n FROM daily_notice_dispatch_intents').get().n,1);assert.equal(await h.badge.noticeEvidenceReady(b),false);const f=h.badge.noticeIntentFence(b,tokens[0]);h.sqlite.exec("CREATE TABLE fence_fixture(value TEXT); INSERT INTO fence_fixture VALUES('before')");assert.equal(Number((await h.env.DB.prepare(`UPDATE fence_fixture SET value='candidate' WHERE ${f.sql}`).bind(...f.args).run()).meta.changes),1);assert.equal(await b.outer.canDispatch('DAILY',b.outerToken,b.context),false);h.sqlite.exec("UPDATE expense_projection_generation_jobs SET lease_token='changed_token'");assert.equal(Number((await h.env.DB.prepare(`UPDATE fence_fixture SET value='unsafe' WHERE ${f.sql}`).bind(...f.args).run()).meta.changes),0);assert.equal(await h.badge.holdNotice(tokens[0]),true);assert.equal(await h.badge.holdNotice(tokens[0]),false);assert.equal(h.sqlite.prepare('SELECT state FROM daily_notice_dispatch_intents').get().state,'REVIEW');}finally{h.close();}});
test('source lease changes before consume are rejected without intent',async()=>{const h=setup();try{const b=await readyNotice(h),prepare=h.DB.prepare;h.DB.prepare=function(sql){const s=prepare.call(this,sql);if(sql.includes('INSERT INTO daily_notice_dispatch_intents')){const run=s.run.bind(s);s.run=async()=>{h.sqlite.exec("UPDATE expense_projection_generation_jobs SET lease_token='changed_token'");return run();};}return s;};assert.equal(await h.badge.consumeNotice(b),null);assert.equal(h.sqlite.prepare('SELECT count(*) n FROM daily_notice_dispatch_intents').get().n,0);}finally{h.close();}});
test('lost intent acknowledgement is held with no automatic retry or grant',async()=>{const h=setup();try{const b=await readyNotice(h),prepare=h.DB.prepare;h.DB.prepare=function(sql){const s=prepare.call(this,sql);if(sql.includes('INSERT INTO daily_notice_dispatch_intents')){const run=s.run.bind(s);s.run=async()=>{await run();throw Error('lost acknowledgement');};}return s;};await assert.rejects(h.badge.consumeNotice(b),/INTENT_UNKNOWN/);h.DB.prepare=prepare;assert.equal(h.sqlite.prepare('SELECT state FROM daily_notice_dispatch_intents').get().state,'REVIEW');assert.equal(await h.badge.inspectUnresolvedNotice(),'REVIEW');assert.equal(await h.badge.consumeNotice(b),null);assert.equal(await h.badge.noticeEvidenceReady(b),false);}finally{h.close();}});
test('unknown held intent blocks a subsequent notice window and never expires automatically',async()=>{const h=setup();try{const b=await readyNotice(h),token=await h.badge.consumeNotice(b);assert.ok(token);assert.equal(await h.badge.holdNotice(token),true);assert.throws(()=>h.sqlite.exec("UPDATE daily_edit_coordination SET state='AVAILABLE',window_token=NULL,cutover_generation=NULL,notice_until=NULL,deadline=NULL,updated_at=strftime('%Y-%m-%dT%H:%M:%fZ','now')"),/coordination (review|window immutable)/);const {requestDailyEditNotice,readDailyEditStatus}=await import('../dist/sheets/daily-edit-coordination.js');assert.ok(['UNKNOWN','REVIEW'].includes(await readDailyEditStatus(h.env)));assert.equal(await requestDailyEditNotice(h.env,b.job,b.syncLease,b.generationLease,b.context,b.outerToken,'another_window_token',15),false);assert.equal(h.sqlite.prepare('SELECT state FROM daily_notice_dispatch_intents').get().state,'REVIEW');}finally{h.close();}});
test('D1 acknowledgement and hold both unavailable leave IN_FLIGHT and prevent retry',async()=>{const h=setup();try{const b=await readyNotice(h),prepare=h.DB.prepare;h.DB.prepare=function(sql){const s=prepare.call(this,sql);if(sql.includes('INSERT INTO daily_notice_dispatch_intents')){const run=s.run.bind(s);s.run=async()=>{await run();throw Error('lost acknowledgement');};}if(sql.includes("UPDATE daily_notice_dispatch_intents SET state='REVIEW'"))s.run=async()=>{throw Error('D1 unavailable');};return s;};await assert.rejects(h.badge.consumeNotice(b),/INTENT_UNKNOWN/);h.DB.prepare=prepare;assert.equal(h.sqlite.prepare('SELECT state FROM daily_notice_dispatch_intents').get().state,'IN_FLIGHT');assert.equal(await h.badge.inspectUnresolvedNotice(),'IN_FLIGHT');assert.equal(await h.badge.consumeNotice(b),null);}finally{h.close();}});
test('receipt and intent are immutable against DELETE, REPLACE, rowid collisions and rollback',async()=>{const h=setup();try{const b=await readyNotice(h),token=await h.badge.consumeNotice(b);assert.ok(token);h.sqlite.exec('PRAGMA recursive_triggers=OFF');const receipt=h.sqlite.prepare('SELECT rowid,* FROM daily_sheet_notice_receipts').get(),intent=h.sqlite.prepare('SELECT rowid,* FROM daily_notice_dispatch_intents').get();assert.throws(()=>h.sqlite.exec('DELETE FROM daily_sheet_notice_receipts'),/retained/);assert.throws(()=>h.sqlite.exec("UPDATE daily_sheet_notice_receipts SET window_token='changed'"),/immutable/);assert.throws(()=>h.sqlite.prepare('INSERT OR REPLACE INTO daily_sheet_notice_receipts(spreadsheet_id,sheet_name,window_token,badge_operation_token,state_range_id,time_range_id,observed_at,ready_after) SELECT spreadsheet_id,sheet_name,window_token,badge_operation_token,state_range_id,time_range_id,observed_at,ready_after FROM daily_sheet_notice_receipts').run(),/collision/);assert.throws(()=>h.sqlite.prepare('INSERT OR REPLACE INTO daily_sheet_notice_receipts(rowid,spreadsheet_id,sheet_name,window_token,badge_operation_token,state_range_id,time_range_id,observed_at,ready_after) VALUES(?,?,?,?,?,?,?,?,?)').run(receipt.rowid,'other','other','other','other','other','other','now','now'),/collision/);assert.throws(()=>h.sqlite.exec('DELETE FROM daily_notice_dispatch_intents'),/retained/);assert.throws(()=>h.sqlite.exec("UPDATE daily_notice_dispatch_intents SET state='IN_FLIGHT'"),/immutable/);assert.throws(()=>h.sqlite.exec("UPDATE daily_notice_dispatch_intents SET state='REVIEW',source_revision=2"),/immutable/);assert.throws(()=>h.sqlite.prepare('INSERT OR REPLACE INTO daily_notice_dispatch_intents SELECT * FROM daily_notice_dispatch_intents').run(),/collision/);assert.throws(()=>h.sqlite.prepare('INSERT OR REPLACE INTO daily_notice_dispatch_intents(rowid,spreadsheet_id,sheet_name,window_token,operation_token,badge_operation_token,sheet_id,state_range_id,time_range_id,preimage_json,expected_values_json,expense_id,source_version,source_revision,cutover_generation,outer_token,sync_lease,generation_lease,state,updated_at) SELECT ?,\'other\',sheet_name,window_token,\'different\',badge_operation_token,sheet_id,state_range_id,time_range_id,preimage_json,expected_values_json,expense_id,source_version,source_revision,cutover_generation,outer_token,sync_lease,generation_lease,state,updated_at FROM daily_notice_dispatch_intents').run(intent.rowid),/collision/);assert.equal(await h.badge.holdNotice(token),true);assert.throws(()=>h.sqlite.exec("UPDATE daily_notice_dispatch_intents SET state='IN_FLIGHT'"),/immutable/);assert.equal(await h.badge.consumeNotice(b),null);}finally{h.close();}});
test('missing receipt retention trigger blocks consumption',async()=>{const h=setup();try{const b=await readyNotice(h);h.sqlite.exec('DROP TRIGGER daily_notice_intent_no_delete');const {readDailyEditStatus}=await import('../dist/sheets/daily-edit-coordination.js');assert.equal(await readDailyEditStatus(h.env),'UNKNOWN');assert.equal(await h.badge.consumeNotice(b),null);assert.equal(h.sqlite.prepare('SELECT count(*) n FROM daily_notice_dispatch_intents').get().n,0);}finally{h.close();}});
test('negative rowid is conservatively held without replacing an existing receipt',async()=>{const h=setup();try{await readyNotice(h);h.sqlite.exec("INSERT INTO daily_sheet_notice_receipts(rowid,spreadsheet_id,sheet_name,window_token,badge_operation_token,state_range_id,time_range_id,observed_at,ready_after) VALUES(-1,'other','other','other','other','a','b','now','later')");assert.throws(()=>h.sqlite.exec("INSERT INTO daily_sheet_notice_receipts(spreadsheet_id,sheet_name,window_token,badge_operation_token,state_range_id,time_range_id,observed_at,ready_after) VALUES('third','third','third','third','a','b','now','later')"),/collision/);assert.equal(h.sqlite.prepare('SELECT count(*) n FROM daily_sheet_notice_receipts').get().n,2);}finally{h.close();}});
test('badge REVIEW after lost finalize acknowledgement cannot be reset, deleted, replaced or consumed',async()=>{const h=setup();try{assert.equal(await h.badge.register(),true);const b=await noticeFixture(h),prepare=h.DB.prepare;h.DB.prepare=function(sql){const s=prepare.call(this,sql);if(sql.includes('SET state=?,operation_token=NULL,verified_operation_token=')){const run=s.run.bind(s);s.run=async()=>{await run();throw Error('lost acknowledgement');};}return s;};await assert.rejects(h.badge.publishNotice(b),/REVIEW/);h.DB.prepare=prepare;assert.equal(state(h),'REVIEW');assert.throws(()=>h.sqlite.exec("UPDATE daily_sheet_badge_journal SET state='READY'"),/transition invalid/);assert.throws(()=>h.sqlite.exec('DELETE FROM daily_sheet_badge_journal'),/retained/);assert.throws(()=>h.sqlite.exec('INSERT OR REPLACE INTO daily_sheet_badge_journal SELECT * FROM daily_sheet_badge_journal'),/collision/);assert.equal(await h.badge.consumeNotice(b),null);}finally{h.close();}});
test('coordination REVIEW cannot be reset, deleted, or replaced',async()=>{const h=setup();try{h.sqlite.exec("UPDATE daily_edit_coordination SET state='NOTICE',window_token='window_token_123456',cutover_generation='fixture_1',notice_until='2099-01-01',deadline='2099-01-01'; UPDATE daily_edit_coordination SET state='REVIEW'");assert.throws(()=>h.sqlite.exec("UPDATE daily_edit_coordination SET state='AVAILABLE',window_token=NULL,cutover_generation=NULL,notice_until=NULL,deadline=NULL"),/coordination (review|window immutable)/);assert.throws(()=>h.sqlite.exec('DELETE FROM daily_edit_coordination'),/retained/);assert.throws(()=>h.sqlite.exec('INSERT OR REPLACE INTO daily_edit_coordination SELECT * FROM daily_edit_coordination'),/collision/);}finally{h.close();}});
test('public status is UNKNOWN without badge and REVIEW when badge is held',async()=>{const h=setup();try{const {readDailyEditStatus}=await import('../dist/sheets/daily-edit-coordination.js');assert.equal(await readDailyEditStatus(h.env),'UNKNOWN');assert.equal(await h.badge.register(),true);assert.equal(await readDailyEditStatus(h.env),'AVAILABLE');h.cells[0].note='human';await assert.rejects(h.badge.publish(),/REVIEW/);assert.equal(await readDailyEditStatus(h.env),'REVIEW');}finally{h.close();}});
