test('active notice binding cannot be rebound or its deadline extended',async()=>{const h=setup();try{assert.equal(await h.badge.register(),true);await noticeFixture(h);assert.throws(()=>h.sqlite.exec("UPDATE daily_edit_coordination SET window_token='different_window'"),/window immutable/);assert.throws(()=>h.sqlite.exec("UPDATE daily_edit_coordination SET badge_generation_lease='different_lease'"),/window immutable/);assert.throws(()=>h.sqlite.exec("UPDATE daily_edit_coordination SET deadline='2999-01-01'"),/window immutable/);h.sqlite.exec("UPDATE daily_edit_coordination SET updated_at=strftime('%Y-%m-%dT%H:%M:%fZ','now','+1 seconds')");}finally{h.close();}});
