test('reviewed release status becomes UNKNOWN when the confirmed badge timestamp expires',async()=>{const h=setup();const now=Date.now;try{const f=await reviewedReleaseFixture(h),{resolveDailyReviewedRelease}=await import('../dist/admin/daily-reviewed-release.js'),{readDailyEditStatus}=await import('../dist/sheets/daily-edit-coordination.js');await resolveDailyReviewedRelease(h.env,{witnessActionId:f.actionId,actionId:f.releaseId,evidenceDigest:f.releaseView.evidenceDigest,editorsPaused:true,legacyWritersDrained:true});assert.equal(await h.badge.publish(),true);assert.equal(await readDailyEditStatus(h.env),'AVAILABLE');Date.now=()=>now()+121000;assert.equal(await readDailyEditStatus(h.env),'UNKNOWN');}finally{Date.now=now;h.close();}});
test('a reviewed daily resolution permits a new notice without reusing its old receipt',async()=>{const h=setup();try{const f=await reviewedReleaseFixture(h),{resolveDailyReviewedRelease}=await import('../dist/admin/daily-reviewed-release.js'),{ExpenseProjectionRuntimeJournal}=await import('../dist/sheets/expense-projection-runtime-journal.js');await resolveDailyReviewedRelease(h.env,{witnessActionId:f.actionId,actionId:f.releaseId,evidenceDigest:f.releaseView.evidenceDigest,editorsPaused:true,legacyWritersDrained:true});assert.equal(await h.badge.publish(),true);h.sqlite.exec("INSERT INTO expense_events(expense_id,message_id,line_user_id,description,amount_satang,payment_key,source_wallet,category,transaction_date,status,created_at,version) VALUES('exp_next','msg_next','fixture','Next',10000,'transfer','SHOP_BANK','general','2026-10-26','CONFIRMED','now',1); INSERT INTO sync_jobs(job_id,entity_type,entity_key,entity_version,trace_id,status,updated_at,lease_until,lease_token) VALUES('next','EXPENSE','exp_next',1,'next','PROCESSING','now','2099-01-01T00:00:00.000Z','next_owner'); INSERT INTO expense_projection_generation_jobs(spreadsheet_id,cutover_generation,expense_id,source_version,source_revision,state,lease_token,lease_until,created_at,updated_at) VALUES('workbook_private','fixture_1','exp_next',1,1,'IN_FLIGHT','next_generation','2099-01-01T00:00:00.000Z','now','now')");const job={kind:'SHEETS_SYNC',entityType:'EXPENSE',entityKey:'exp_next',entityVersion:1,traceId:'next'},lease={generation:'fixture_1',revision:1,token:'next_generation'},outer=new ExpenseProjectionRuntimeJournal(h.env,job,'next_owner',lease),context=await outer.context(),token=await outer.begin('DAILY',context);assert.ok(token);assert.equal(await outer.requestDailyNotice(token,context,'next_window_123456',15),true);assert.equal(h.sqlite.prepare('SELECT count(*) n FROM daily_sheet_notice_receipts').get().n,1);assert.equal(h.sqlite.prepare('SELECT window_token FROM daily_edit_coordination').get().window_token,'next_window_123456');const oldReceipt=h.sqlite.prepare('SELECT * FROM daily_sheet_notice_receipts WHERE window_token=?').get(f.b.windowToken),b2={job,syncLease:'next_owner',generationLease:lease,context,outerToken:token,windowToken:'next_window_123456'};assert.equal(await h.badge.publishNotice(b2),true);const nextReceipt=h.sqlite.prepare('SELECT * FROM daily_sheet_notice_receipts WHERE window_token=?').get(b2.windowToken);assert.ok(nextReceipt);assert.notEqual(nextReceipt.badge_operation_token,oldReceipt.badge_operation_token);h.sqlite.exec("DROP TRIGGER daily_notice_receipt_no_update; UPDATE daily_sheet_notice_receipts SET observed_at=strftime('%Y-%m-%dT%H:%M:%fZ','now','-16 seconds'),ready_after=strftime('%Y-%m-%dT%H:%M:%fZ','now','-1 seconds') WHERE window_token='next_window_123456'; CREATE TRIGGER daily_notice_receipt_no_update BEFORE UPDATE ON daily_sheet_notice_receipts BEGIN SELECT RAISE(ABORT,'daily receipt immutable'); END");assert.deepEqual(h.sqlite.prepare('SELECT * FROM daily_sheet_notice_receipts WHERE window_token=?').get(f.b.windowToken),oldReceipt);const nextNotice=await h.badge.consumeNotice(b2);assert.ok(nextNotice);assert.equal(await h.badge.consumeNotice(f.b),null);const next=h.sqlite.prepare('SELECT * FROM daily_notice_dispatch_intents WHERE window_token=?').get(b2.windowToken);assert.equal(next.expense_id,'exp_next');assert.equal(next.outer_token,token);assert.equal(next.sync_lease,'next_owner');assert.equal(next.generation_lease,'next_generation');assert.equal(next.badge_operation_token,nextReceipt.badge_operation_token);assert.notEqual(next.operation_token,f.noticeToken);assert.equal(h.sqlite.prepare("SELECT state FROM expense_projection_generation_jobs WHERE expense_id='exp_fixture'").get().state,'REVIEW');assert.equal(h.sqlite.prepare("SELECT count(*) n FROM expense_projection_runtime_intents WHERE projection IN ('RAW','DETAIL')").get().n,0);}finally{h.close();}});
test('concurrent reviewed release attempts resolve a window at most once',async()=>{const h=setup();try{const f=await reviewedReleaseFixture(h),{resolveDailyReviewedRelease}=await import('../dist/admin/daily-reviewed-release.js'),base={witnessActionId:f.actionId,evidenceDigest:f.releaseView.evidenceDigest,editorsPaused:true,legacyWritersDrained:true},results=await Promise.allSettled([resolveDailyReviewedRelease(h.env,{...base,actionId:f.releaseId}),resolveDailyReviewedRelease(h.env,{...base,actionId:'33333333-3333-4333-8333-333333333333'})]);assert.equal(results.filter(x=>x.status==='fulfilled').length,1);assert.equal(h.sqlite.prepare('SELECT count(*) n FROM daily_reviewed_resolutions').get().n,1);assert.equal(h.sqlite.prepare("SELECT state FROM expense_projection_runtime_intents WHERE projection='DAILY'").get().state,'VERIFIED');assert.equal(f.badgeWrites(),0);}finally{h.close();}});
test('witness advancement remains available before resolution when reviewed release is enabled',async()=>{const h=setup();try{const f=await witnessRecoveryFixture(h),{advanceDailyWitness,inspectDailyRecovery}=await import('../dist/admin/daily-recovery.js');h.env.DAILY_REVIEWED_RELEASE_ENABLED='true';const view=await inspectDailyRecovery(h.env,f.b.windowToken);assert.equal(view.evidenceDigest,f.view.evidenceDigest);assert.equal((await advanceDailyWitness(h.env,{windowToken:f.b.windowToken,actionId:f.actionId,evidenceDigest:view.evidenceDigest,editorsPaused:true,legacyWritersDrained:true})).state,'WITNESS_ADVANCED_STILL_HELD');assert.equal(h.sqlite.prepare('SELECT state FROM daily_notice_dispatch_intents').get().state,'REVIEW');assert.equal(f.writes(),0);}finally{h.close();}});
test('reviewed release routes require admin auth and never return sheet values',async()=>{const h=setup();try{const f=await reviewedReleaseFixture(h);h.env.ADMIN_TOKEN='x'.repeat(40);const {handleAdmin}=await import('../dist/admin/handler.js'),url='https://example.test/admin/daily-recovery/inspect-release',body=JSON.stringify({witnessActionId:f.actionId});const denied=await handleAdmin(new Request(url,{method:'POST',body}),h.env,{});assert.equal(denied.status,401);assert.equal(h.sqlite.prepare('SELECT count(*) n FROM daily_reviewed_resolutions').get().n,0);const allowed=await handleAdmin(new Request(url,{method:'POST',headers:{authorization:`Bearer ${h.env.ADMIN_TOKEN}`},body}),h.env,{}),view=await allowed.json();assert.equal(allowed.status,200);assert.equal(view.state,'DAILY_EVIDENCE_MATCHED');assert.equal(allowed.headers.get('cache-control'),'no-store, max-age=0');assert.doesNotMatch(JSON.stringify(view),/Synthetic|exp_fixture|MALIPANG_EXPENSE/);assert.equal(f.badgeWrites(),0);}finally{h.close();}});
test('reviewed DAILY release leaves existing RAW and DETAIL reviews untouched',async()=>{const h=setup();try{const f=await reviewedReleaseFixture(h),{resolveDailyReviewedRelease}=await import('../dist/admin/daily-reviewed-release.js');for(const projection of ['RAW','DETAIL'])h.sqlite.prepare("INSERT INTO expense_projection_runtime_intents(spreadsheet_id,expense_id,source_version,source_revision,projection,state,operation_token,cutover_generation,admission_watermark,updated_at) VALUES('workbook_private','exp_fixture',1,2,?,'REVIEW',?,'fixture_1',0,'now')").run(projection,projection+'_token');await resolveDailyReviewedRelease(h.env,{witnessActionId:f.actionId,actionId:f.releaseId,evidenceDigest:f.releaseView.evidenceDigest,editorsPaused:true,legacyWritersDrained:true});assert.deepEqual(h.sqlite.prepare("SELECT projection,state FROM expense_projection_runtime_intents WHERE projection IN ('RAW','DETAIL') ORDER BY projection").all().map(r=>[r.projection,r.state]),[['DETAIL','REVIEW'],['RAW','REVIEW']]);assert.equal(h.sqlite.prepare('SELECT state FROM expense_projection_generation_jobs').get().state,'REVIEW');assert.equal(f.badgeWrites(),0);}finally{h.close();}});
test('authenticated release route resolves only the verified daily projection',async()=>{const h=setup();try{const f=await reviewedReleaseFixture(h);h.env.ADMIN_TOKEN='x'.repeat(40);const {handleAdmin}=await import('../dist/admin/handler.js'),body=JSON.stringify({witnessActionId:f.actionId,actionId:f.releaseId,evidenceDigest:f.releaseView.evidenceDigest,editorsPaused:true,legacyWritersDrained:true}),url='https://example.test/admin/daily-recovery/release';const denied=await handleAdmin(new Request(url,{method:'POST',body}),h.env,{});assert.equal(denied.status,401);assert.equal(h.sqlite.prepare('SELECT count(*) n FROM daily_reviewed_resolutions').get().n,0);const response=await handleAdmin(new Request(url,{method:'POST',headers:{authorization:`Bearer ${h.env.ADMIN_TOKEN}`},body}),h.env,{}),view=await response.json();assert.equal(response.status,200);assert.equal(view.state,'DAILY_RESOLVED_REMAINING_UNCONFIRMED');assert.equal(response.headers.get('cache-control'),'no-store, max-age=0');assert.doesNotMatch(JSON.stringify(view),/Synthetic|exp_fixture|MALIPANG_EXPENSE/);assert.equal(h.sqlite.prepare("SELECT state FROM expense_projection_runtime_intents WHERE projection='DAILY'").get().state,'VERIFIED');assert.equal(h.sqlite.prepare('SELECT state FROM expense_projection_generation_jobs').get().state,'REVIEW');assert.equal(f.badgeWrites(),0);}finally{h.close();}});
